import type { Locator, Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { expectText, expectUrl, expectVisible } from '@/utils/assertions/ui-assertions';
import { API_ROUTES, UI_ROUTES } from '@/utils/constants/routes';
import type { Product } from '@/utils/types/shop';

/** The product list `/#/search`. */
export class SearchPage extends BasePage {
  private readonly productCards: Locator;

  constructor(page: Page) {
    super(page);
    this.productCards = page.locator('app-search-result article.product');
  }

  private productCard(product: Product): Locator {
    return this.productCards.filter({
      has: this.page.locator('.name').getByText(product.name, { exact: true }),
    });
  }

  private addToBasketButton(product: Product): Locator {
    return this.productCard(product).getByRole('button', { name: 'Add to Basket' });
  }

  async open(): Promise<void> {
    await this.openRoute(UI_ROUTES.search);
    await this.shouldSeePage();
  }

  /** Clicks `Add to Basket` and waits until the server has answered the basket change. */
  async clickAddToBasket(product: Product): Promise<void> {
    const basketChange = this.page.waitForResponse(
      (response) => response.url().includes(API_ROUTES.basketItems) && response.request().method() !== 'GET',
    );
    await this.addToBasketButton(product).click();
    await basketChange;
  }

  async shouldSeePage(): Promise<void> {
    await expectUrl(this.page, new RegExp(`${UI_ROUTES.search}$`), 'Product list');
    await expectVisible(this.productCards.first(), 'First product card');
  }

  async shouldSeeProduct(product: Product): Promise<void> {
    const card = this.productCard(product);
    await expectVisible(card, `Product card of ${product.name}`);
    await expectText(card.locator('.price'), product.price, `Price of ${product.name}`);
    await expectVisible(this.addToBasketButton(product), `Button \`Add to Basket\` of ${product.name}`);
  }
}
