import type { Locator, Page } from '@playwright/test';
import { expectStaysHidden, expectText, expectVisible } from '@/utils/assertions/ui-assertions';
import { BASKET_COUPON_URL_PATTERN } from '@/utils/constants/routes';
import { SHOP_MESSAGES } from '@/utils/constants/shop-data';

/** The panel `Add a coupon` on the payment step. */
export class CouponPanelComponent {
  private readonly header: Locator;
  private readonly couponField: Locator;
  private readonly redeemButton: Locator;
  private readonly confirmation: Locator;
  private readonly error: Locator;
  private readonly discountMessage: Locator;

  constructor(private readonly page: Page) {
    const panel = page.locator('app-payment mat-expansion-panel').filter({ hasText: 'Add a coupon' });
    this.header = panel.getByRole('button', { name: /Add a coupon/ });
    const body = panel.getByRole('region');
    this.couponField = body.getByRole('textbox', { name: 'Coupon' });
    this.redeemButton = body.getByRole('button', { name: 'Redeem' });
    this.confirmation = body.locator('.confirmation');
    this.error = body.locator('.error');
    this.discountMessage = body.getByText(SHOP_MESSAGES.discountPrefix);
  }

  async open(): Promise<void> {
    await this.header.click();
    await expectVisible(this.couponField, 'Field `Coupon`');
  }

  /** Types the code, clicks `Redeem` and waits for the answer of the server. */
  async redeem(code: string): Promise<void> {
    await this.couponField.fill(code);
    const redeemAnswer = this.page.waitForResponse((response) => BASKET_COUPON_URL_PATTERN.test(response.url()));
    await this.redeemButton.click();
    await redeemAnswer;
  }

  async shouldSeePanel(): Promise<void> {
    await expectVisible(this.header, 'Panel `Add a coupon`');
  }

  async shouldSeeDiscountApplied(percent: number): Promise<void> {
    await expectText(this.confirmation, SHOP_MESSAGES.discountApplied(percent), 'Coupon confirmation');
  }

  async shouldSeeInvalidCouponError(): Promise<void> {
    await expectText(this.error, SHOP_MESSAGES.invalidCoupon, 'Coupon error');
  }

  async shouldNotSeeDiscount(): Promise<void> {
    await expectStaysHidden(this.discountMessage, `Message "${SHOP_MESSAGES.discountPrefix} ..."`);
  }
}

