import { test } from '@/fixtures/customer.fixture';
import { checkoutWithSavedAddress, continueWithDeliveryMethod } from '@/tests/helpers/checkout-flows';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import { COUPON_DISCOUNT_PERCENT, DELIVERY_METHODS, PRODUCTS, SAVED_CARD } from '@/utils/constants/shop-data';
import { CouponHelper } from '@/utils/helpers/coupon-helper';
import type { OrderTotals } from '@/utils/types/shop';

const INVALID_CODE = 'abcdefghij';
const EXPECTED_SUMMARY: OrderTotals = {
  items: '17.98¤',
  delivery: '0.99¤',
  promotion: '0.00¤',
  total: '18.97¤',
};

test.use({
  customerSetup: {
    withSavedAddressAndCard: true,
    basket: [{ product: PRODUCTS.eggfruitJuice, quantity: 2 }],
  },
});

test('Invalid coupon and expired coupon', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.coupon],
  annotation: { type: 'test-case', description: 'TC-06' },
}, async ({ basketPage, addressSelectPage, deliveryMethodPage, paymentPage, orderSummaryPage }) => {
  await test.step('1. Open the basket, check out and continue with the saved address', async () => {
    await basketPage.open();
    await checkoutWithSavedAddress(basketPage, addressSelectPage);
    await deliveryMethodPage.shouldSeePage();
  });

  await test.step('2. Select `One Day Delivery` and click `Continue`', async () => {
    await continueWithDeliveryMethod(deliveryMethodPage, DELIVERY_METHODS.oneDay);
    await paymentPage.shouldSeePage();
  });

  await test.step('3. Redeem the invalid code', async () => {
    await paymentPage.openCouponPanel();
    await paymentPage.redeemCoupon(INVALID_CODE);
    await paymentPage.shouldSeeInvalidCouponError();
    await paymentPage.shouldNotSeeDiscount();
  });

  await test.step('4. Redeem the coupon of the previous month', async () => {
    await paymentPage.redeemCoupon(CouponHelper.previousMonthCode(COUPON_DISCOUNT_PERCENT));
    await paymentPage.shouldSeeInvalidCouponError();
    await paymentPage.shouldNotSeeDiscount();
  });

  await test.step('5. Select the saved card and click `Continue`', async () => {
    await paymentPage.selectCard(SAVED_CARD);
    await paymentPage.clickContinue();
    await orderSummaryPage.shouldSeePage();
    await orderSummaryPage.shouldSeeTotals(EXPECTED_SUMMARY);
  });
});
