import type { Locator, Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { CouponPanelComponent } from '@/page-objects/checkout/components/coupon-panel.component';
import { SavedCardsComponent } from '@/page-objects/checkout/components/saved-cards.component';
import { expectDisabled, expectEnabled, expectText, expectVisible } from '@/utils/assertions/ui-assertions';
import { SHOP_MESSAGES } from '@/utils/constants/shop-data';
import type { SavedCard } from '@/utils/types/shop';

/** Checkout step `My Payment Options`: saved cards, the wallet and the coupon panel. */
export class PaymentPage extends BasePage {
  private readonly title: Locator;
  private readonly walletBalance: Locator;
  private readonly payWithWalletButton: Locator;
  private readonly continueButton: Locator;
  private readonly couponPanel: CouponPanelComponent;
  private readonly savedCards: SavedCardsComponent;

  constructor(page: Page) {
    super(page);
    const content = page.locator('app-payment');
    this.title = content.getByRole('heading', { name: 'My Payment Options' });
    this.walletBalance = content.getByText('Wallet Balance').locator('xpath=following-sibling::span');
    this.payWithWalletButton = content.getByRole('button', { name: /^Pay / });
    this.continueButton = content.getByRole('button', { name: 'Proceed to review' });
    this.couponPanel = new CouponPanelComponent(page);
    this.savedCards = new SavedCardsComponent(page);
  }

  async selectCard(card: SavedCard): Promise<void> {
    await this.savedCards.selectCard(card);
  }

  async clickContinue(): Promise<void> {
    await this.continueButton.click();
  }

  async clickPayWithWallet(): Promise<void> {
    await this.payWithWalletButton.click();
  }

  async openCouponPanel(): Promise<void> {
    await this.couponPanel.open();
  }

  async redeemCoupon(code: string): Promise<void> {
    await this.couponPanel.redeem(code);
  }

  async shouldSeePage(): Promise<void> {
    await expectVisible(this.title, 'Title `My Payment Options`');
  }

  async shouldSeeSavedCard(card: SavedCard): Promise<void> {
    await this.savedCards.shouldSeeCard(card);
  }

  async shouldSeeCouponPanel(): Promise<void> {
    await this.couponPanel.shouldSeePanel();
  }

  async shouldSeeDiscountApplied(percent: number): Promise<void> {
    await this.couponPanel.shouldSeeDiscountApplied(percent);
  }

  async shouldSeeInvalidCouponError(): Promise<void> {
    await this.couponPanel.shouldSeeInvalidCouponError();
  }

  async shouldNotSeeDiscount(): Promise<void> {
    await this.couponPanel.shouldNotSeeDiscount();
  }

  /** `balance` without the currency sign, as the page shows it, for example `5.00`. */
  async shouldSeeWalletBalance(balance: string): Promise<void> {
    await expectText(this.walletBalance, balance, 'Wallet Balance');
  }

  async shouldSeePayWithWalletButton(amount: string): Promise<void> {
    await expectText(this.payWithWalletButton, SHOP_MESSAGES.payWithWallet(amount), 'Wallet pay button');
  }

  async shouldSeePayWithWalletDisabled(): Promise<void> {
    await expectDisabled(this.payWithWalletButton, 'Wallet pay button');
  }

  async shouldSeePayWithWalletEnabled(): Promise<void> {
    await expectEnabled(this.payWithWalletButton, 'Wallet pay button');
  }
}
import type { Locator, Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import {
  expectCount,
  expectDisabled,
  expectStaysHidden,
  expectText,
  expectTextHolds,
  expectUrl,
  expectVisible,
} from '@/utils/assertions/ui-assertions';
import { API_ROUTES, UI_ROUTES } from '@/utils/constants/routes';
import { SHOP_MESSAGES } from '@/utils/constants/shop-data';
import type { BasketLine, Product } from '@/utils/types/shop';

/** The basket `/#/basket`. */
export class BasketPage extends BasePage {
  private readonly title: Locator;
  private readonly rows: Locator;
  private readonly totalPrice: Locator;
  private readonly checkoutButton: Locator;

  constructor(page: Page) {
    super(page);
    const basket = page.locator('app-basket');
    this.title = basket.getByRole('heading', { name: /Your Basket/ });
    this.rows = basket.locator('mat-row');
    this.totalPrice = basket.getByText(/^Total Price:/);
    this.checkoutButton = basket.getByRole('button', { name: 'Checkout' });
  }

  private row(product: Product): Locator {
    return this.rows.filter({
      has: this.page.locator('mat-cell.mat-column-product').getByText(product.name, { exact: true }),
    });
  }

  private quantity(product: Product): Locator {
    return this.row(product).locator('mat-cell.mat-column-quantity span.cell-initial-font');
  }

  /** Clicks a button of a basket row and waits until the server has answered the basket change. */
  private async clickRowButton(button: Locator): Promise<void> {
    const basketChange = this.page.waitForResponse(
      (response) => response.url().includes(API_ROUTES.basketItems) && response.request().method() !== 'GET',
    );
    await button.click();
    await basketChange;
  }

  async open(): Promise<void> {
    await this.openRoute(UI_ROUTES.basket);
    await this.shouldSeePage();
  }

  /** Loads the basket again from the server. */
  async reload(): Promise<void> {
    await this.page.reload({ waitUntil: 'domcontentloaded' });
    await this.shouldSeePage();
  }

  async clickIncreaseQuantity(product: Product): Promise<void> {
    await this.clickRowButton(this.row(product).locator('mat-cell.mat-column-quantity button').last());
  }

  async clickDecreaseQuantity(product: Product): Promise<void> {
    await this.clickRowButton(this.row(product).locator('mat-cell.mat-column-quantity button').first());
  }

  async clickRemove(product: Product): Promise<void> {
    await this.clickRowButton(this.row(product).locator('mat-cell.mat-column-remove button'));
  }

  /** Clicks the plus button once for each missing item and waits for each new quantity. */
  async increaseQuantityTo(product: Product, targetQuantity: number): Promise<void> {
    const current = Number((await this.quantity(product).innerText()).trim());
    for (let quantity = current + 1; quantity <= targetQuantity; quantity += 1) {
      await this.clickIncreaseQuantity(product);
      await expectText(this.quantity(product), String(quantity), `Quantity of ${product.name}`);
    }
  }

  async clickCheckout(): Promise<void> {
    await this.checkoutButton.click();
  }

  async shouldSeePage(): Promise<void> {
    await expectUrl(this.page, new RegExp(`${UI_ROUTES.basket}$`), 'Basket page');
    await expectVisible(this.title, 'Title `Your Basket`');
  }

  async shouldSeeLine(line: BasketLine): Promise<void> {
    const { product, quantity } = line;
    await expectVisible(this.row(product), `Basket row of ${product.name}`);
    await expectText(this.quantity(product), String(quantity), `Quantity of ${product.name}`);
    await expectText(this.row(product).locator('mat-cell.mat-column-price'), product.price, `Price of ${product.name}`);
  }

  async shouldSeeOnlyLines(lines: BasketLine[]): Promise<void> {
    await expectCount(this.rows, lines.length, 'Number of basket rows');
    for (const line of lines) {
      await this.shouldSeeLine(line);
    }
  }

  async shouldKeepQuantity(product: Product, quantity: number): Promise<void> {
    await expectTextHolds(this.quantity(product), String(quantity), `Quantity of ${product.name}`);
  }

  async shouldNotSeeProduct(product: Product): Promise<void> {
    await expectStaysHidden(this.row(product), `Basket row of ${product.name}`);
  }

  async shouldSeeNoProducts(): Promise<void> {
    await expectCount(this.rows, 0, 'Number of basket rows');
  }

  async shouldSeeTotalPrice(amount: string): Promise<void> {
    await expectText(this.totalPrice, SHOP_MESSAGES.totalPrice(amount), 'Basket total');
  }

  async shouldKeepTotalPrice(amount: string): Promise<void> {
    await expectTextHolds(this.totalPrice, SHOP_MESSAGES.totalPrice(amount), 'Basket total');
  }

  async shouldSeeCheckoutDisabled(): Promise<void> {
    await expectDisabled(this.checkoutButton, 'Button `Checkout`');
  }
}

