    await addressSelectPage.shouldSeeSavedAddress(SAVED_ADDRESS);
  });

  await test.step('2. Select the saved address and click `Continue`', async () => {
    await addressSelectPage.selectAddress(SAVED_ADDRESS);
    await addressSelectPage.clickContinue();
    await deliveryMethodPage.shouldSeePage();
    await deliveryMethodPage.shouldSeeDeliveryMethod(DELIVERY_METHODS.oneDay);
    await deliveryMethodPage.shouldSeeDeliveryMethod(DELIVERY_METHODS.fast);
    await deliveryMethodPage.shouldSeeDeliveryMethod(DELIVERY_METHODS.standard);
  });

