    await deliveryMethodPage.selectDeliveryMethod(DELIVERY_METHODS.oneDay);
    await deliveryMethodPage.clickContinue();
    await paymentPage.shouldSeePage();
    await paymentPage.shouldSeeSavedCard(SAVED_CARD);
    await paymentPage.shouldSeeCouponPanel();
  });

  await test.step('4. Redeem the 10% coupon of the current month', async () => {
    await paymentPage.openCouponPanel();
    await paymentPage.redeemCoupon(CouponHelper.currentMonthCode(COUPON_DISCOUNT_PERCENT));
    await paymentPage.shouldSeeDiscountApplied(COUPON_DISCOUNT_PERCENT);
  });

  await test.step('5. Select the saved card and click `Continue`', async () => {
    await paymentPage.selectCard(SAVED_CARD);
    await paymentPage.clickContinue();
    await orderSummaryPage.shouldSeePage();
    await orderSummaryPage.shouldSeeTotals(EXPECTED_SUMMARY);
  });
});
import type { Locator, Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { CouponPanelComponent } from '@/page-objects/checkout/components/coupon-panel.component';
import { SavedCardsComponent } from '@/page-objects/checkout/components/saved-cards.component';
import { expectDisabled, expectEnabled, expectText, expectVisible } from '@/utils/assertions/ui-assertions';
import { SHOP_MESSAGES } from '@/utils/constants/shop-data';
import type { SavedCard } from '@/utils/types/shop';

/** Checkout step `My Payment Options`: saved cards, the wallet and the coupon panel. */
export class PaymentPage extends BasePage {
  private readonly title: Locator;
  private readonly walletBalance: Locator;
  private readonly payWithWalletButton: Locator;
  private readonly continueButton: Locator;
  private readonly couponPanel: CouponPanelComponent;
  private readonly savedCards: SavedCardsComponent;

  constructor(page: Page) {
    super(page);
    const content = page.locator('app-payment');
    this.title = content.getByRole('heading', { name: 'My Payment Options' });
    this.walletBalance = content.getByText('Wallet Balance').locator('xpath=following-sibling::span');
    this.payWithWalletButton = content.getByRole('button', { name: /^Pay / });
    this.continueButton = content.getByRole('button', { name: 'Proceed to review' });
