import { test } from '@/fixtures/customer.fixture';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import { PRODUCTS, PURCHASE_LIMIT_PER_PRODUCT, SHOP_MESSAGES } from '@/utils/constants/shop-data';

const PRODUCT = PRODUCTS.appleJuice;
const TOTAL_AT_LIMIT = '9.95¤';
const LIMIT_ERROR = SHOP_MESSAGES.purchaseLimit(PURCHASE_LIMIT_PER_PRODUCT);

test('Purchase limit for one product', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.cart],
  annotation: { type: 'test-case', description: 'TC-04' },
}, async ({ searchPage, basketPage }) => {
  await test.step('1. Open the product list and click `Add to Basket` on the product', async () => {
    await searchPage.open();
    await searchPage.clickAddToBasket(PRODUCT);
    await searchPage.snackBar.shouldSeeMessage(SHOP_MESSAGES.placedIntoBasket(PRODUCT.name));
    await searchPage.navbar.shouldSeeBasketCounter(1);
  });

  await test.step('2. Open the basket and click the plus button until the quantity is 5', async () => {
    await basketPage.open();
    await basketPage.increaseQuantityTo(PRODUCT, PURCHASE_LIMIT_PER_PRODUCT);
    await basketPage.shouldSeeLine({ product: PRODUCT, quantity: PURCHASE_LIMIT_PER_PRODUCT });
    await basketPage.shouldSeeTotalPrice(TOTAL_AT_LIMIT);
    await basketPage.snackBar.shouldNotSeeErrorMessage();
  });

  await test.step('3. Click the plus button one more time', async () => {
    await basketPage.clickIncreaseQuantity(PRODUCT);
    await basketPage.snackBar.shouldSeeErrorMessage(LIMIT_ERROR);
  });

  await test.step('4. Read the basket', async () => {
    await basketPage.shouldKeepQuantity(PRODUCT, PURCHASE_LIMIT_PER_PRODUCT);
    await basketPage.shouldKeepTotalPrice(TOTAL_AT_LIMIT);
    await basketPage.navbar.shouldKeepBasketCounter(PURCHASE_LIMIT_PER_PRODUCT);
    await basketPage.reload();
    await basketPage.shouldSeeOnlyLines([{ product: PRODUCT, quantity: PURCHASE_LIMIT_PER_PRODUCT }]);
    await basketPage.shouldSeeTotalPrice(TOTAL_AT_LIMIT);
    await basketPage.navbar.shouldSeeBasketCounter(PURCHASE_LIMIT_PER_PRODUCT);
    await basketPage.snackBar.shouldNotSeeErrorMessage();
  });

  await test.step('5. Open the product list and click `Add to Basket` on the product', async () => {
    await searchPage.open();
    await searchPage.clickAddToBasket(PRODUCT);
    await searchPage.snackBar.shouldSeeErrorMessage(LIMIT_ERROR);
    await searchPage.navbar.shouldKeepBasketCounter(PURCHASE_LIMIT_PER_PRODUCT);
  });
});

