import { test } from '@/fixtures/customer.fixture';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import { PRODUCTS, SHOP_MESSAGES } from '@/utils/constants/shop-data';

const PRODUCT = PRODUCTS.eggfruitJuice;
const EXPECTED_TOTAL = '8.99¤';

test('Add a product to the basket', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.cart],
  annotation: { type: 'test-case', description: 'TC-02' },
}, async ({ searchPage, basketPage }) => {
  await test.step('1. Open the product list', async () => {
    await searchPage.open();
    await searchPage.shouldSeeProduct(PRODUCT);
    await searchPage.navbar.shouldSeeBasketCounter(0);
  });

  await test.step('2. Click `Add to Basket` on the product', async () => {
    await searchPage.clickAddToBasket(PRODUCT);
    await searchPage.snackBar.shouldSeeMessage(SHOP_MESSAGES.placedIntoBasket(PRODUCT.name));
    await searchPage.navbar.shouldSeeBasketCounter(1);
  });

  await test.step('3. Open the basket with the button `Your Basket`', async () => {
    await searchPage.navbar.clickYourBasket();
    await basketPage.shouldSeePage();
    await basketPage.shouldSeeOnlyLines([{ product: PRODUCT, quantity: 1 }]);
  });

  await test.step('4. Read the total of the basket', async () => {
    await basketPage.shouldSeeTotalPrice(EXPECTED_TOTAL);
  });
});
